const input = $input.first().json;
let raw = input.output || input.text || JSON.stringify(input);

// Keep the original raw output for debugging
const originalRaw = raw;

// Remove markdown fences if present
raw = raw.replace(/```json|```/g, '').trim();

// Try to extract the main JSON object
const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  raw = raw.slice(firstBrace, lastBrace + 1);
}

// Normalize common quote issues
raw = raw
  .replace(/[“”]/g, '"')
  .replace(/[‘’]/g, "'")
  .replace(/\u00A0/g, ' ');

// Remove trailing commas before } or ]
raw = raw.replace(/,\s*([}\]])/g, '$1');

// Escape literal newlines inside JSON strings
function escapeNewlinesInStrings(str) {
  let result = '';
  let inString = false;
  let escaped = false;

  for (let i = 0; i < str.length; i++) {
    const ch = str[i];

    if (escaped) {
      result += ch;
      escaped = false;
      continue;
    }

    if (ch === '\\') {
      result += ch;
      escaped = true;
      continue;
    }

    if (ch === '"') {
      result += ch;
      inString = !inString;
      continue;
    }

    if (inString && (ch === '\n' || ch === '\r')) {
      // convert literal line breaks inside strings into escaped newlines
      if (ch === '\r' && str[i + 1] === '\n') {
        i++;
      }
      result += '\\n';
      continue;
    }

    result += ch;
  }

  return result;
}

raw = escapeNewlinesInStrings(raw);

let content;
let parseError = null;

try {
  content = JSON.parse(raw);
} catch (e) {
  parseError = e.message;
  throw new Error(
    'Invalid JSON from AI Content node.\n\n' +
    'Parse error: ' + e.message + '\n\n' +
    'SANITIZED RAW OUTPUT:\n' + raw + '\n\n' +
    'ORIGINAL RAW OUTPUT:\n' + originalRaw
  );
}

const category = input.category || 'Area Rug';
const focus = input.focus || '';

return [{
  json: {
    content,
    category,
    focus,
    originalRaw,
    sanitizedRaw: raw,
    parseError
  }
}];

const data = $input.first().json;
const c = data.content || {};
const category = data.category || 'Area Rug';
const focus = data.focus || 'Natural & Sustainable';
const today = new Date().toLocaleDateString('en-US', {year: 'numeric', month: 'long', day: 'numeric'});
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Key Metrics Cards
