let metricsHtml = metrics.map(m => `
  <div class="insight-card">
    <div class="number">${esc(m.value)}</div>
    <div class="label">${esc(m.label)}</div>
  </div>
`).join('');

// Data Foundation
const df = c.data_foundation || {};
let p2List = (df.p2_insights || []).map(i => `<li>${esc(i)}</li>`).join('');
let p3List = (df.p3_insights || []).map(i => `<li>${esc(i)}</li>`).join('');

// Content Ideas
const ideas = c.content_ideas || [];
let ideasHtml = ideas.map(i => {
  const kws = (i.seo_keywords || []).map(k => `<span class="keyword">${esc(k)}</span>`).join('');
  return `
  <div class="content-card">
    <div class="content-card-header">
      <div class="type">${esc(i.type)}</div>
      <h4>${esc(i.title)}</h4>
    </div>
    <div class="content-card-body">
      <p>${esc(i.description)}</p>
      <div class="data-tag">📊 ${esc(i.data_connection)}</div>
      ${kws ? `<div class="keywords">${kws}</div>` : ''}
    </div>
  </div>`;
}).join('');

// Social Captions
const soc = c.social_captions || {};
let igHtml = (soc.instagram || []).map(p => `
  <div class="social-post">
    <div class="platform-badge ig">Instagram</div>
    <p>${esc(p.caption)}</p>
    <div class="hashtags">${(p.hashtags || []).join(' ')}</div>
  </div>
`).join('');
let pinHtml = (soc.pinterest || []).map(p => `
  <div class="social-post">
    <div class="platform-badge pin">Pinterest</div>
    <p><strong>${esc(p.title)}</strong></p>
    <p>${esc(p.description)}</p>
  </div>
`).join('');
let fbHtml = (soc.facebook || []).map(p => `
  <div class="social-post">
    <div class="platform-badge fb">Facebook</div>
    <p>${esc(p.post)}</p>
  </div>
`).join('');
let ttHtml = (soc.tiktok || []).map(p => `
  <div class="social-post">
    <div class="platform-badge tt">TikTok</div>
    <p><strong>Hook:</strong> ${esc(p.hook)}</p>
    <p>${esc(p.script)}</p>
  </div>
`).join('');

// Campaigns
const camps = c.campaigns || [];
let campsHtml = camps.map(camp => {
  const det = camp.details || {};
  let detailsHtml = Object.entries(det).map(([k, v]) => `
    <div class="campaign-detail">
      <h5>${k.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())}</h5>
      <p>${esc(v)}</p>
    </div>
  `).join('');
  return `
  <div class="campaign-card">
    <h4>Campaign: "${esc(camp.name)}"</h4>
    <div class="tagline">"${esc(camp.tagline)}"</div>
    <p>${esc(camp.description)}</p>
    <div class="campaign-details">${detailsHtml}</div>
  </div>`;
}).join('');

// Email Subjects
const emails = c.email_subjects || [];
let emailsHtml = emails.map(e => {
  const rateClass = e.open_rate === 'high' ? 'high' : 'medium';
  return `
  <div class="email-subject">
    <span class="icon">${e.icon || '📧'}</span>
    <span class="subject-text">${esc(e.subject)}</span>
    <span class="open-rate ${rateClass}">Est. ${e.open_rate === 'high' ? 'High' : 'Medium'} Open</span>
  </div>`;
}).join('');

// Competitive Angles
const angles = c.competitive_angles || [];
let anglesHtml = angles.map(a => `
  <div class="competitive-angle">
    <h4>Angle: "${esc(a.title)}"</h4>
    <p><strong>Competitor Gap:</strong> ${esc(a.competitor_gap)}</p>
    <p><strong>Wayfair Opportunity:</strong> ${esc(a.wayfair_opportunity)}</p>
  </div>
`).join('');

// Content Priorities
const priorities = c.content_priorities || [];
let prioritiesHtml = priorities.map(p => {
  const prioClass = p.priority <= 2 ? 'high' : 'medium';
  return `
  <div class="recommendation">
    <div class="priority ${prioClass}">${p.priority}</div>
    <div class="recommendation-content">
      <h4>${esc(p.title)}</h4>
      <p>${esc(p.rationale)}</p>
    </div>
  </div>`;
}).join('');

